import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer, UiPressArgument } from 'claude-code'

import type { CacheTtl, LastResponse } from '../types'
import {
  BAR_CELLS,
  FALLBACK_THRESHOLD,
  cacheView,
  formatTokens,
  hitRate,
  redrawOffsets,
  splitParagraphs,
  ttlFromTranscript,
  weather,
} from './logic'

const last = atom({ plugin: 'cache-leiste', key: 'last' } as const, null)
const ttl = atom({ plugin: 'cache-leiste', key: 'ttl' } as const, '5m')
const isTtlRead = atom({ plugin: 'cache-leiste', key: 'isTtlRead' } as const, false)
const context = atom({ plugin: 'cache-leiste', key: 'context' } as const, {
  percent: null,
  threshold: FALLBACK_THRESHOLD,
  isThresholdRead: false,
})
const now = atom({ plugin: 'cache-leiste', key: 'now' } as const, 0)
const isCollapsed = atom({ plugin: 'cache-leiste', key: 'isCollapsed' } as const, false)

/** Wie viel vom Ende des Protokolls gelesen wird, um die Cache-Laufzeit zu finden. */
const TRANSCRIPT_TAIL_BYTES = '2000000'

// Modulvariablen: nach einem Neuladen leer, alles Gezeichnete liegt in $.state.
let timers: Timer[] = []
let isBusy = false
/** Die letzte bekannte Kontextgröße; nach einem Compact bleibt sie bis zur nächsten Antwort stehen. */
let contextTokens: number | undefined
let pendingCompact: { before?: number; after?: number; fallback?: string; isLogged: boolean } | undefined
let compactSummary: string | undefined
/**
 * Läuft gerade ein Compact, den der Knopf ausgelöst hat? Dessen Ereignisse
 * laufen unter dem Aufruf des Mods und erreichen dessen Hooks nicht; der Knopf
 * schreibt die Zusammenfassung dann selbst.
 */
let isOwnCompact = false

async function setNow($: EngineInterface) {
  const t = await $.clock.now()
  await update($, now, () => t)
}

/** Zeichnet ab der letzten Antwort jede Minute neu, dazu beim Wechsel auf Gelb und Rot. */
async function startTicking($: EngineInterface) {
  for (const timer of timers) timer.cancel()
  timers = []
  await setNow($)

  const response = await read($, last)
  if (response === null) return
  const elapsed = (await $.clock.now()) - response.at

  for (const offset of redrawOffsets(await read($, ttl))) {
    if (offset <= elapsed) continue
    timers.push($.clock.after(offset - elapsed, () => void setNow($)))
  }
}

async function setTtl($: EngineInterface, value: CacheTtl) {
  const before = await read($, ttl)
  await update($, ttl, () => value)
  await update($, isTtlRead, () => true)
  await $.store.set('ttl', value)
  if (before !== value) await startTicking($)
}

async function readTtlFromTranscript($: EngineInterface, path: string) {
  let text: string | undefined
  try {
    const tail = await $.process.run(['tail', '-c', TRANSCRIPT_TAIL_BYTES, path], { timeoutMs: 5000 })
    if (tail.exitCode === 0) text = tail.stdout
  } catch {
    // Kein tail auf diesem Rechner: dann die Datei selbst, solange sie unter 4 MiB ist.
  }
  if (text === undefined) {
    try {
      text = await $.fs.read(path)
    } catch {
      return
    }
  }
  const found = ttlFromTranscript(text)
  if (found !== undefined) await setTtl($, found)
}

async function readThreshold($: EngineInterface) {
  try {
    const usage = await $.session.usage({ breakdown: 'summary' })
    const breakdown = usage.context.breakdown
    const tokens = breakdown?.isAutoCompactEnabled ? breakdown.autoCompactThreshold : undefined
    if (tokens === undefined || usage.context.window <= 0) return
    const threshold = Math.round((tokens / usage.context.window) * 100)
    await update($, context, fill => ({ ...fill, threshold, isThresholdRead: true }))
  } catch {
    // Schwelle nicht lesbar: es bleibt bei 83 %.
  }
}

async function setContext($: EngineInterface, percent: number | undefined, tokens: number | undefined) {
  if (tokens !== undefined) contextTokens = tokens
  await update($, context, fill => ({ ...fill, percent: percent ?? null }))
}

/** Nach einem Compact ist der alte Cache nichts mehr wert, bis die nächste Antwort kommt. */
async function resetAfterCompact($: EngineInterface) {
  await update($, last, () => null)
  await update($, context, fill => ({ ...fill, percent: null }))
  await startTicking($)
}

function writeSummary($: EngineInterface, before: number | undefined, after: number | undefined, summary: string | undefined) {
  const from = before === undefined ? '?' : formatTokens(before)
  const to = after === undefined ? '?' : formatTokens(after)
  $.ui.log(`Compact: ${from} → ${to} Tokens. Damit macht Claude weiter:`)
  if (summary === undefined || summary.trim() === '') {
    $.ui.log('(keine Zusammenfassung erhalten)')
    return
  }
  for (const chunk of splitParagraphs(summary)) $.ui.log(chunk)
}

/** Die Nachricht, mit der das Gespräch nach dem Compact beginnt: die Zusammenfassung. */
function summaryOf(messages: readonly { role: string; text: string }[]): string | undefined {
  return messages.find(message => message.role === 'user' && message.text.trim() !== '')?.text
}

/** Die Größe nach dem Compact, geschätzt, solange noch keine Antwort sie gemeldet hat. */
async function estimateTokens($: EngineInterface): Promise<number | undefined> {
  try {
    const usage = await $.session.usage({ breakdown: 'summary' })
    return usage.context.tokens ?? usage.context.breakdown?.totalTokens
  } catch {
    return undefined
  }
}

function logCompact($: EngineInterface) {
  if (pendingCompact === undefined || pendingCompact.isLogged) return
  pendingCompact.isLogged = true
  const { before, after, fallback } = pendingCompact
  const summary = compactSummary ?? fallback
  compactSummary = undefined
  writeSummary($, before, after, summary)
}

async function compactNow($: EngineInterface) {
  const before = contextTokens
  const result = await $.session.compact()
  if (result.skip !== undefined) {
    $.ui.toast(`Compact übersprungen: ${result.skip}`)
    return
  }
  await resetAfterCompact($)
  writeSummary($, result.tokensBefore ?? before, result.tokensAfter, summaryOf(result.messages))
}

async function compactQueued($: EngineInterface) {
  $.ui.toast('/compact ist eingereiht und startet, sobald Claude fertig ist.')
  try {
    const ran = await $.command.run({ command: 'compact' })
    if (ran.text !== undefined && /error|fehler|failed|not enough/i.test(ran.text)) {
      $.ui.toast(`/compact: ${ran.text}`)
      return
    }
    const before = contextTokens
    await resetAfterCompact($)
    writeSummary($, before, await estimateTokens($), summaryOf(await $.session.messages()))
  } catch {
    $.ui.toast('/compact ließ sich nicht einreihen.')
  }
}

async function compact($: EngineInterface, press: UiPressArgument, isWorkingAtDraw: boolean) {
  if (isOwnCompact) {
    $.ui.toast('Compact läuft schon.')
    return
  }
  isOwnCompact = true
  try {
    // In der Desktop-App und während einer Runde geht der direkte Aufruf nicht: einreihen.
    if (press.surface !== 'terminal' || isBusy || isWorkingAtDraw) {
      await compactQueued($)
      return
    }
    try {
      await compactNow($)
    } catch {
      await compactQueued($)
    }
  } finally {
    isOwnCompact = false
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    const savedTtl = await $.store.get('ttl')
    if (savedTtl === '5m' || savedTtl === '1h') await update($, ttl, () => savedTtl)
    const savedCollapsed = await $.store.get('isCollapsed')
    if (typeof savedCollapsed === 'boolean') await update($, isCollapsed, () => savedCollapsed)

    const usage = await $.session.usage()
    await setContext($, usage.context.percent, usage.context.tokens)
    await readThreshold($)
    await startTicking($)

    return started
  })

  // Bei einer fortgesetzten Session: wann die letzte Antwort kam und mit welcher Laufzeit.
  on('classic.SessionStart', async ($, e, next) => {
    const result = await next(e)
    if (e.seconds_since_last_response !== undefined && (await read($, last)) === null) {
      const at = (await $.clock.now()) - e.seconds_since_last_response * 1000
      await update($, last, () => ({ at, hitRate: null }))
    }
    if (e.source === 'resume' || e.source === 'fork') await readTtlFromTranscript($, e.transcript_path)
    await startTicking($)

    return result
  }).catch(($, e, next) => next(e))

  on('turn.start', ($, e, next) => {
    isBusy = true
    return next(e)
  })

  // Jede Antwort des Hauptgesprächs frischt den Cache auf und bringt die Hit-Rate mit.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    if (e.agentId === undefined && result.usage !== null) {
      const response: LastResponse = { at: await $.clock.now(), hitRate: hitRate(result.usage) }
      await update($, last, () => response)
      await startTicking($)
    }
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) {
      isBusy = false
      if (!(await read($, context)).isThresholdRead) await readThreshold($)
    }
    return result
  })

  // Am Ende jeder Runde steht die letzte Antwort im Protokoll: daraus die echte Laufzeit.
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (e.agent_id === undefined) await readTtlFromTranscript($, e.transcript_path)
    return result
  }).catch(($, e, next) => next(e))

  on('classic.PostModelSwitch', async ($, e, next) => {
    const result = await next(e)
    await setTtl($, e.cache_ttl)
    await update($, context, fill => ({ ...fill, isThresholdRead: false }))
    await readThreshold($)
    return result
  }).catch(($, e, next) => next(e))

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('context')) await setContext($, e.context.percent, e.context.tokens)
    return next(e)
  })

  on('classic.PostCompact', async ($, e, next) => {
    const result = await next(e)
    if (isOwnCompact) return result
    compactSummary = e.compact_summary
    if (pendingCompact !== undefined) logCompact($)
    return result
  }).catch(($, e, next) => next(e))

  // /compact, selbst getippt (der Knopf schreibt seine Zusammenfassung selbst, siehe compact).
  on('session.compact', async ($, e, next) => {
    const before = contextTokens
    const result = await next(e)
    if (isOwnCompact || e.agentId !== undefined || result.skip !== undefined) return result

    await resetAfterCompact($)
    if (e.trigger !== 'auto' && e.trigger !== 'precompute') {
      pendingCompact = { before: result.tokensBefore ?? before, after: result.tokensAfter, fallback: summaryOf(result.messages), isLogged: false }
      // Die Zusammenfassung aus PostCompact abwarten, wenn sie nicht schon da ist.
      if (compactSummary !== undefined) logCompact($)
      else $.clock.after(1500, () => logCompact($))
    }
    return result
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const response = await read($, last)
    const cacheTtl = await read($, ttl)
    const ttlKnown = await read($, isTtlRead)
    const fill = await read($, context)
    const t = await read($, now)
    const collapsed = await read($, isCollapsed)
    const isWorkingAtDraw = e.props.isWorking

    const view = response === null ? undefined : cacheView(response.at, cacheTtl, Math.max(t, response.at))
    const sky = fill.percent === null ? '☀️' : weather(fill.percent, fill.threshold)
    const isStorm = sky === '⛈️'
    const thresholdText = `${fill.isThresholdRead ? '' : '~'}${fill.threshold} %`
    const percentText = fill.percent === null ? '–' : `${fill.percent} %`
    const minutesText =
      view === undefined ? '–' : view.minutes === 0 ? 'abgelaufen' : `${view.minutes} Min`
    const minutesColor = view === undefined ? undefined : view.color

    const toggle = (
      <Button
        key="toggle"
        plain
        dimColor
        label={collapsed ? '▸' : '◂'}
        onPress={async () => {
          const value = await update($, isCollapsed, c => !c)
          await $.store.set('isCollapsed', value)
        }}
      />
    )

    if (collapsed || e.props.bodyColumns < 60) {
      return (
        <Box flexDirection="row">
          <Text>{sky} </Text>
          <Text color={minutesColor} dimColor={view === undefined}>
            {minutesText}
          </Text>
          <Text dimColor> · </Text>
          <Text>{percentText} </Text>
          {toggle}
        </Box>
      )
    }

    const bar =
      view === undefined ? (
        <Text dimColor>{'░'.repeat(BAR_CELLS)}</Text>
      ) : (
        <Text>
          <Text color={view.color}>{'█'.repeat(view.filled)}</Text>
          <Text dimColor>{'░'.repeat(BAR_CELLS - view.filled)}</Text>
        </Text>
      )
    const hit = response?.hitRate ?? null

    return (
      <Box flexDirection="row">
        <Text dimColor>Cache{ttlKnown ? ` ${cacheTtl === '1h' ? '1 h' : '5 Min'}` : ''}: </Text>
        <Text color={minutesColor} dimColor={view === undefined}>
          {minutesText}{' '}
        </Text>
        {bar}
        <Text dimColor> · Hit </Text>
        <Text>{hit === null ? '–' : `${hit} %`}</Text>
        <Text dimColor> · </Text>
        <Text>{sky} </Text>
        <Text dimColor>Kontext </Text>
        <Text color={isStorm ? 'error' : undefined}>{percentText}</Text>
        <Text dimColor> / Compact bei {thresholdText} </Text>
        <Button
          key="compact"
          label="Compact"
          variant={isStorm ? 'primary' : undefined}
          dimColor={isStorm ? undefined : true}
          onPress={press => compact($, press, isWorkingAtDraw)}
        />
        <Text> </Text>
        {toggle}
      </Box>
    )
  })
}

