import type { CacheTtl } from '../types'

export const BAR_CELLS = 20
export const FALLBACK_THRESHOLD = 83
/** Die Zeilen, die das Terminal von einer Log-Zeile zeichnet, sind 2000 Zeichen; etwas Luft bleibt. */
export const LOG_CHUNK = 1800

/** Eine Sekunde Spielraum, damit ein Tick kurz vor der Minutengrenze nicht eine Minute zu viel zeigt. */
const SLACK_MS = 1000

export const ttlMs = (ttl: CacheTtl): number => (ttl === '1h' ? 3_600_000 : 300_000)

export type CacheView = {
  /** Ganze Minuten, aufgerundet; 0 heißt abgelaufen. */
  minutes: number
  /** Gefüllte Kästchen von BAR_CELLS. */
  filled: number
  color: 'success' | 'warning' | 'error'
}

export const cacheView = (at: number, ttl: CacheTtl, now: number): CacheView => {
  const total = ttlMs(ttl)
  const left = Math.max(0, total - (now - at) - SLACK_MS)
  const fraction = left / total
  const minutes = Math.ceil(left / 60_000)
  const filled = Math.min(BAR_CELLS, Math.ceil(fraction * BAR_CELLS))
  const color = fraction > 0.25 ? 'success' : fraction > 0.1 ? 'warning' : 'error'

  return { minutes, filled, color }
}

/**
 * Die Zeitpunkte nach der Antwort, zu denen die Leiste neu gezeichnet wird:
 * jede volle Minute, dazu der Wechsel auf Gelb (75 %) und auf Rot (90 %).
 */
export const redrawOffsets = (ttl: CacheTtl): number[] => {
  const total = ttlMs(ttl)
  const offsets = new Set<number>()

  for (let ms = 60_000; ms <= total; ms += 60_000) offsets.add(ms)
  offsets.add(Math.round(total * 0.75) + SLACK_MS)
  offsets.add(Math.round(total * 0.9) + SLACK_MS)

  return [...offsets].sort((a, b) => a - b)
}

export type Weather = '☀️' | '🌧️' | '⛈️'

export const weather = (percent: number, threshold: number): Weather => {
  const ratio = percent / threshold

  return ratio <= 0.5 ? '☀️' : ratio <= 0.8 ? '🌧️' : '⛈️'
}

export type Usage = {
  input_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

/** Anteil der Input-Tokens, die aus dem Cache kamen, in ganzen Prozent. */
export const hitRate = (usage: Usage): number | null => {
  const read = usage.cache_read_input_tokens ?? 0
  const total = (usage.input_tokens ?? 0) + read + (usage.cache_creation_input_tokens ?? 0)

  return total > 0 ? Math.round((read / total) * 100) : null
}

type TranscriptRow = {
  type?: string
  isSidechain?: boolean
  message?: {
    usage?: {
      cache_creation?: {
        ephemeral_1h_input_tokens?: number
        ephemeral_5m_input_tokens?: number
      } | null
    }
  }
}

/**
 * Liest aus dem Session-Protokoll, mit welcher Laufzeit die letzte Antwort
 * des Hauptgesprächs in den Cache geschrieben hat; undefined, wenn keine
 * Antwort etwas geschrieben hat.
 */
export const ttlFromTranscript = (text: string): CacheTtl | undefined => {
  const lines = text.split('\n')

  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const line = lines[i]?.trim()
    if (!line || !line.includes('"cache_creation"')) continue

    let row: TranscriptRow
    try {
      row = JSON.parse(line) as TranscriptRow
    } catch {
      continue
    }
    if (row.type !== 'assistant' || row.isSidechain === true) continue

    const creation = row.message?.usage?.cache_creation
    if (!creation) continue
    if ((creation.ephemeral_5m_input_tokens ?? 0) > 0) return '5m'
    if ((creation.ephemeral_1h_input_tokens ?? 0) > 0) return '1h'
  }

  return undefined
}

/** Tausender mit Punkt, ohne Intl (die Umgebung des Mods hat keins garantiert). */
export const formatTokens = (n: number): string =>
  String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.')

const hardSplit = (text: string, max: number): string[] => {
  const parts: string[] = []
  let rest = text

  while (rest.length > max) {
    const space = rest.lastIndexOf(' ', max)
    const cut = space > max / 2 ? space : max
    parts.push(rest.slice(0, cut).trimEnd())
    rest = rest.slice(cut).trimStart()
  }
  if (rest.length > 0) parts.push(rest)

  return parts
}

/**
 * Teilt einen langen Text an Absätzen in Stücke von höchstens `max` Zeichen;
 * ein zu langer Absatz wird an Zeilen, eine zu lange Zeile an Wörtern geteilt.
 */
export const splitParagraphs = (text: string, max: number = LOG_CHUNK): string[] => {
  // Jedes Stück mit dem Trenner, der im Text davor stand.
  const pieces: { text: string; sep: string }[] = []

  for (const paragraph of text.trim().split(/\n\s*\n/)) {
    if (paragraph.length <= max) {
      pieces.push({ text: paragraph, sep: '\n\n' })
      continue
    }
    paragraph.split('\n').forEach((line, i) => {
      const sep = i === 0 ? '\n\n' : '\n'
      hardSplit(line, max).forEach((part, j) => pieces.push({ text: part, sep: j === 0 ? sep : ' ' }))
    })
  }

  const chunks: string[] = []
  let current = ''

  for (const piece of pieces) {
    if (current === '') {
      current = piece.text
    } else if (current.length + piece.sep.length + piece.text.length > max) {
      chunks.push(current)
      current = piece.text
    } else {
      current = current + piece.sep + piece.text
    }
  }
  if (current.trim() !== '') chunks.push(current)

  return chunks
}

