export type CacheTtl = '5m' | '1h'

/** Die letzte Antwort des Hauptgesprächs: wann sie kam und wie viel aus dem Cache. */
export type LastResponse = { at: number; hitRate: number | null }

/** Kontextfüllung und Auto-Compact-Schwelle, beides in Prozent des Kontextfensters. */
export type ContextFill = {
  percent: number | null
  threshold: number
  isThresholdRead: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'cache-leiste': {
      last: LastResponse | null
      ttl: CacheTtl
      isTtlRead: boolean
      context: ContextFill
      now: number
      isCollapsed: boolean
    }
  }
}
